mapper.sql:
FROM "operating_companies" "oc" INNER JOIN "agencies" "a" ON "a"."business_corp_id" = "oc"."business_corp_id" WHERE "oc"."del_flag" = 0 AND "a"."del_flag" = 0 AND "oc"."business_corp_id" = #{businessCorpId}
AND "oc"."operating_name" LIKE CONCAT(#{operatingName}, '%')
AND "oc"."available_flag" = #{availableFlag}
